import java.util.Scanner;

public class Main {
    static String findGreeting(String str) {
        String word = "hello";
        int i = 0;
        for (char l : str.toCharArray()) {
            if (i < word.length() && l == word.charAt(i)) {
                i++;
            }
        }
        return i == word.length() ? "YES" : "NO";
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String data = scanner.nextLine();
        System.out.println(findGreeting(data));
        scanner.close();
    }
}
